import{_ as i,o as t,c as a,a2 as e}from"./chunks/framework.YT-FC_Xx.js";const k=JSON.parse('{"title":"订阅模板","description":"","frontmatter":{},"headers":[],"relativePath":"guide/subscription-templates.md","filePath":"guide/subscription-templates.md","lastUpdated":1792768999000}'),o={name:"guide/subscription-templates.md"};function l(n,s,r,d,h,p){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="订阅模板" tabindex="-1">订阅模板 <a class="header-anchor" href="#订阅模板" aria-label="Permalink to &quot;订阅模板&quot;">​</a></h1><p>想让订阅按自己的规则、策略组和 DNS 来，可以用 <strong>订阅模板</strong>：把自己的 Mihomo、sing-box 或 Surge 配置当骨架，面板只负责把订阅里的节点放进去，其余内容原样下发。网上现成的模板大多可以直接用，不需要再套一层 subconverter。</p><h2 id="添加模板" tabindex="-1">添加模板 <a class="header-anchor" href="#添加模板" aria-label="Permalink to &quot;添加模板&quot;">​</a></h2><p><strong>订阅</strong> 页右上角点 <strong>模板</strong> → <strong>新建模板</strong>：</p><ul><li><strong>格式</strong>：Mihomo、sing-box 或 Surge，一个模板只对应一种格式</li><li><strong>内容</strong>： <ul><li><strong>选择规则</strong>：下拉快速选择极简、均衡（推荐）、完整或自定义，勾选需要的分类后创建模板</li><li><strong>源码编辑</strong>：直接粘贴配置，可以随时修改。节点列表留空即可（<code>proxies: []</code>），面板会填进去</li><li><strong>从网址获取</strong>：填模板地址（例如 GitHub 上的 raw 链接），面板每天下载一次，下载失败继续用上次的内容。网址模板不能直接改，点 <strong>复制为本地模板</strong> 得到一份可编辑的副本</li></ul></li><li><strong>插入分组</strong>：点 🇭🇰 香港、🇯🇵 日本等按钮，在合适的位置插入一个按地区自动收节点的测速组；记得在“节点选择”之类的组里引用它</li><li><strong>用示例开始</strong>：内容为空时可以用一份最小的示例起步</li><li><strong>检查</strong>：检查格式，并用某个订阅的节点预演每个策略组能收到哪些节点；没有节点的组标为“空组”</li></ul><h2 id="选择规则创建模板" tabindex="-1">选择规则创建模板 <a class="header-anchor" href="#选择规则创建模板" aria-label="Permalink to &quot;选择规则创建模板&quot;">​</a></h2><p>默认使用 <strong>均衡规则</strong>，选中私有网络、AI、GitHub、YouTube、Telegram、Google、国内服务、非中国 8 个类别；<strong>极简规则</strong> 只选私有网络、国内服务、非中国，<strong>完整规则</strong> 选中全部 19 类。单独勾选或取消分类后会切换为 <strong>自定义</strong>，切换预设会保留额外添加的自定义规则。</p><ul><li><strong>规则去向与顺序</strong>：为每条规则选择节点选择、某个策略组、直连或拦截，用上下箭头调整优先级。从上往下匹配，第一条命中后生效；具体服务应放在包含它的大类前面。</li><li><strong>添加自定义规则</strong>：支持完整域名、域名后缀、域名关键词和 IPv4 / IPv6 CIDR。域名不带协议、路径或通配符，例如 <code>example.com</code>；CIDR 如 <code>192.0.2.0/24</code>、<code>2001:db8::/32</code>。新规则放在最前面，仍可调整顺序。</li><li><strong>策略组</strong>：默认只提供自动选择测速组；香港、日本、美国等地区组可按需快捷添加，可修改名称和节点名称正则，或添加、删除分组。删除分组后，原来指向它的规则会回到“节点选择”。</li><li><strong>兜底去向</strong>：没有任何规则命中的流量走这里。</li><li><strong>生成并预览</strong>：按顺序查看每条规则的分流去向，代理节点详情可折叠展开，也可查看生成的配置；保存后可重新打开继续勾选编辑，再到订阅的“规则”页选用。</li></ul><p>选择规则生成的 sing-box 模板支持 <strong>1.12+</strong> 客户端；Mihomo 模板的规则集用 YAML 格式，Stash 和 Shadowrocket 选用同一个模板也能读。规则集沿用 MetaCubeX / blackmatrix7，客户端按天更新；面板无需增加服务。保存时生成配置，之后改了规则要重新保存才会更新。切到“源码编辑”会先生成当前配置，手动修改并保存后改为源码模板；已有任意源码不会自动反向转换为规则选择。</p><h2 id="节点怎么进策略组" tabindex="-1">节点怎么进策略组 <a class="header-anchor" href="#节点怎么进策略组" aria-label="Permalink to &quot;节点怎么进策略组&quot;">​</a></h2><p>按各客户端<strong>本来就支持</strong>的写法，模板里写好，面板不改：</p><table tabindex="0"><thead><tr><th>格式</th><th>写法</th><th>说明</th></tr></thead><tbody><tr><td>Mihomo</td><td><code>include-all: true</code>，可加 <code>filter: &quot;(?i)港|HK&quot;</code>、<code>exclude-filter</code></td><td>客户端自己按 filter 收节点；多个表达式用 <code>\`</code> 分隔</td></tr><tr><td>sing-box</td><td><code>&quot;outbounds&quot;: [&quot;{all}&quot;]</code>，可加 <code>&quot;filter&quot;: [{&quot;action&quot;: &quot;include&quot;, &quot;keywords&quot;: [&quot;港|HK&quot;]}]</code></td><td>面板把 <code>{all}</code> 换成符合 filter 的节点名（sing-box-subscribe 的写法）；<code>action</code> 为 <code>exclude</code> 时排除；组里一个节点都没有时换成 <code>direct</code>，避免 sing-box 报错</td></tr><tr><td>Surge</td><td><code>include-all-proxies=1</code>，可加 <code>policy-regex-filter=港|HK</code></td><td>客户端自己按正则收节点</td></tr></tbody></table><p>例如 Mihomo：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">proxies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [] </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 面板填入订阅里的节点</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">proxy-groups</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">🚀 节点选择</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">select</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    proxies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">🇭🇰 香港</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DIRECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">🇭🇰 香港</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">url-test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    include-all</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;(?i)港|HK|Hong Kong&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GEOIP,CN,DIRECT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">MATCH,🚀 节点选择</span></span></code></pre></div><p>面板在生成配置时：</p><ul><li>Mihomo：只替换 <code>proxies</code> 这一段，模板的其余文字（包括注释和顺序）原样保留</li><li>sing-box：节点加在 <code>outbounds</code> 末尾，WireGuard 节点放进 <code>endpoints</code></li><li>Surge：节点写在 <code>[Proxy]</code> 段原有内容之后；没有 <code>[Proxy]</code> 段时自动加上</li><li>开了 <a href="./subscription-rules#链式代理">链式代理</a> 时，自动加上“落地节点”“中转节点”两个组</li><li>节点名和模板里的组名重复时，节点名后面加 <code>#2</code></li></ul><h2 id="在订阅里使用" tabindex="-1">在订阅里使用 <a class="header-anchor" href="#在订阅里使用" aria-label="Permalink to &quot;在订阅里使用&quot;">​</a></h2><p>编辑订阅 → <strong>规则</strong> → <strong>订阅模板</strong>，Mihomo、sing-box、Surge、Stash、Shadowrocket 各选一个模板：</p><ul><li>选了模板的客户端拿到按模板生成的配置，下面的 <strong>内置分组与规则</strong> 对它不生效</li><li>没选模板的客户端照旧用内置规则；Loon、Quantumult X 暂不支持模板</li><li>Stash 没单独选模板时，沿用 Mihomo 的模板；Mihomo 模板里有 <code>mrs</code> 规则集（Stash 读不了）时不沿用，改用内置规则</li><li><strong>Stash、Shadowrocket</strong> 用 Mihomo 格式的模板，可以和 Mihomo 共用同一个： <ul><li>这两个客户端不一定认 <code>include-all</code> / <code>filter</code>，面板会把这类组展开成具体的节点列表（模板里原本写的成员排在前面），一个节点都匹配不到时放一个 <code>DIRECT</code>，避免客户端报空组</li><li>展开时和 Mihomo 收节点的规则一致：<code>filter</code> 支持 <code>(?!...)</code>、<code>(?&lt;!...)</code> 这类前后断言（如“其他地区”常用的 <code>^(?!.*(港|日|美)).*$</code>），<code>exclude-type</code> 按协议排除（如 <code>Shadowsocks|Http</code>），用 YAML 锚点 <code>&lt;&lt;: *xxx</code> 继承来的 <code>include-all</code>、<code>filter</code> 也会生效</li><li>规则集要用 <code>yaml</code> 或 <code>text</code> 格式：<code>mrs</code> 只有 Mihomo 能读，模板检查时会提醒</li><li>Shadowrocket 开了链式代理时，落地节点按中转各复制一份（“落地（经 中转）”），和不用模板时一样</li><li>Shadowrocket 选了模板后下发的是完整配置，订阅详情里的 Shadowrocket 按钮会改为导入配置</li></ul></li><li>筛选、改名、加国旗、去重和脚本照常先执行，处理后的节点才放进模板</li><li><strong>预览</strong> 页的 <strong>模板策略组</strong> 里能看到每个组收到了哪些节点</li></ul><p>有订阅在用的模板不能删除，也不能改格式；先在订阅里换掉。备份会包含模板。</p><h3 id="按服务独立选择节点" tabindex="-1">按服务独立选择节点 <a class="header-anchor" href="#按服务独立选择节点" aria-label="Permalink to &quot;按服务独立选择节点&quot;">​</a></h3><p>规则编辑器默认开启“按服务生成独立策略组”。每个已选分类和“漏网之鱼”各生成一个选择组，可在客户端分别选择节点、节点分组或直连。类别的规则去向是该组的默认选择。sing-box 的拦截类别使用原生拒绝动作。关闭此选项则直接按规则去向转发。</p>`,22)])])}const g=i(o,[["render",l]]);export{k as __pageData,g as default};
